import { Deck } from '@deck.gl/core';
import { IconLayer, TextLayer } from '@deck.gl/layers';
import { TileLayer } from '@deck.gl/geo-layers';
import { BitmapLayer } from '@deck.gl/layers';
import { csvParse } from 'd3-dsv';

// Company colors mapping - Flame palette
const COMPANY_COLORS = {
  'ASSEMBLEIA DE DEUS VITORIA EM CRISTO': [255, 69, 0, 255],     // Red-Orange
  'EDITORA CENTRAL GOSPEL LTDA': [255, 140, 0, 255],             // Dark Orange  
  'TALLI EVENTOS E PRODUCOES GOSPEL LTDA': [255, 215, 0, 255],   // Gold
  'CONSELHO INTERDENOMINACIONAL DE MINISTROS EVANGELICOS DO BRASIL': [255, 255, 0, 255], // Yellow
  'EDITORA VIDA VITORIOSA LTDA': [255, 165, 0, 255],             // Orange
  'ESM INVESTIMENTO E PARTICIPACOES LTDA': [220, 20, 60, 255]    // Crimson
};

// Ensure container is ready
const mapContainer = document.getElementById('map');
console.log('Map container:', mapContainer, mapContainer.offsetWidth, mapContainer.offsetHeight);

const deck = new Deck({
  container: mapContainer,
  width: window.innerWidth,
  height: window.innerHeight,
  initialViewState: {
    longitude: -43.2096, // Rio de Janeiro longitude
    latitude: -22.9035,  // Rio de Janeiro latitude  
    zoom: 10,            // Zoom level for ~15km view
    pitch: 0,
    bearing: 0           // 0 = North is up (default orientation)
  },
  controller: {
    dragRotate: false,  // Disable rotation - keep north pointing up
    touchRotate: false  // Disable touch rotation
  },
  canvas: null, // Let Deck.gl create its own canvas
  onLoad: () => {
    console.log('Deck.gl loaded successfully');
    console.log('Canvas created:', deck.canvas);
  },
  onError: (error) => {
    console.error('Deck.gl error:', error);
  },
  onResize: ({width, height}) => {
    console.log('Deck resized:', width, height);
  }
});

// Function to load and parse CSV data
async function loadData() {
  try {
    const csvPath = import.meta.env.DEV ? './imperio_malafaia.csv' : '/malafaia/imperio_malafaia.csv';
    const response = await fetch(csvPath);
    const csvText = await response.text();
    const data = csvParse(csvText);
    
    // Filter out invalid coordinates and convert to numbers
    const validData = data.filter(d => {
      const lat = parseFloat(d.latitude);
      const lng = parseFloat(d.longitude);
      return !isNaN(lat) && !isNaN(lng) && lat !== 0 && lng !== 0;
    }).map(d => ({
      razao_social: d.razao_social,
      latitude: parseFloat(d.latitude),
      longitude: parseFloat(d.longitude),
      data_inicio_atividade: d.data_inicio_atividade,
      year: parseInt(d.data_inicio_atividade.split('-')[0]),
      coordinates: [parseFloat(d.longitude), parseFloat(d.latitude)]
    }));

    console.log(`Loaded ${validData.length} valid data points`);
    return validData;
  } catch (error) {
    console.error('Error loading CSV data:', error);
    return [];
  }
}

// Create Latin cross icon data using ✝ symbol with specific color
function createCrossIcon(color = '#FF3232') {
  const canvas = document.createElement('canvas');
  canvas.width = 24;
  canvas.height = 24;
  const ctx = canvas.getContext('2d');
  
  // Draw ✝ symbol with specified color
  ctx.fillStyle = color;
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('✝', 12, 12);
  
  return {
    url: canvas.toDataURL(),
    width: 24,
    height: 24
  };
}


// Create icon layer with cross symbols
function createIconLayer(data) {
  console.log('Creating icon layer with data:', data.length, 'points');
  console.log('Sample data point:', data[0]);
  console.log('Coordinate bounds:', {
    minLat: Math.min(...data.map(d => d.latitude)),
    maxLat: Math.max(...data.map(d => d.latitude)),
    minLng: Math.min(...data.map(d => d.longitude)),
    maxLng: Math.max(...data.map(d => d.longitude))
  });

  // Create icon atlas with all company cross icons
  const canvas = document.createElement('canvas');
  const companies = Object.keys(COMPANY_COLORS);
  canvas.width = 24;
  canvas.height = 24 * companies.length;
  const ctx = canvas.getContext('2d');
  
  const iconMapping = {};
  companies.forEach((company, index) => {
    const y = index * 24;
    const rgbaColor = COMPANY_COLORS[company];
    const color = `rgb(${rgbaColor[0]}, ${rgbaColor[1]}, ${rgbaColor[2]})`;
    
    // Draw cross for this company
    ctx.fillStyle = color;
    ctx.font = '20px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('✝', 12, y + 12);
    
    iconMapping[company] = {
      x: 0,
      y: y,
      width: 24,
      height: 24
    };
  });
  
  return new IconLayer({
    id: 'icon-layer',
    data,
    pickable: true,
    iconAtlas: canvas.toDataURL(),
    iconMapping: iconMapping,
    getIcon: d => d.razao_social,
    getPosition: d => d.coordinates,
    getSize: 16, // Medium size
    updateTriggers: {
      getIcon: data,
      getPosition: data
    },
    onClick: ({object, x, y}) => {
      if (object) {
        const tooltip = document.querySelector('.deck-tooltip') || createTooltip();
        tooltip.style.left = x + 'px';
        tooltip.style.top = y + 'px';
        tooltip.style.display = 'block';
        tooltip.innerHTML = `
          <div><strong>Nome:</strong> ${object.razao_social}</div>
          <div><strong>Ano Início:</strong> ${object.data_inicio_atividade}</div>
        `;
      }
    },
    onHover: ({object, x, y}) => {
      if (object) {
        const tooltip = document.querySelector('.deck-tooltip') || createTooltip();
        tooltip.style.left = x + 'px';
        tooltip.style.top = y + 'px';
        tooltip.style.display = 'block';
        tooltip.innerHTML = `
          <div><strong>Nome:</strong> ${object.razao_social}</div>
          <div><strong>Ano Início:</strong> ${object.data_inicio_atividade}</div>
        `;
      } else {
        const tooltip = document.querySelector('.deck-tooltip');
        if (tooltip) tooltip.style.display = 'none';
      }
    }
  });
}

// Create text layer with year labels
function createTextLayer(data) {
  return new TextLayer({
    id: 'text-layer',
    data: isSliderActive ? data : [], // Only show data when slider is active
    pickable: false,
    getPosition: d => d.coordinates,
    getText: d => d.year.toString(),
    getSize: 14, // Bigger text size
    getColor: d => {
      // Get company color and return RGB array
      const companyColor = COMPANY_COLORS[d.razao_social];
      return companyColor ? companyColor : [255, 255, 255, 200]; // Fallback to white
    },
    getAngle: 0,
    getTextAnchor: 'start',
    getAlignmentBaseline: 'center',
    getPixelOffset: [20, 0], // Offset to the right of the icon
    fontFamily: 'Arial, sans-serif',
    fontWeight: 'bold',
    updateTriggers: {
      getPosition: data,
      getText: data,
      getColor: data,
      data: isSliderActive // Update when slider state changes
    }
  });
}

// Create tooltip element
function createTooltip() {
  const tooltip = document.createElement('div');
  tooltip.className = 'deck-tooltip';
  tooltip.style.position = 'absolute';
  tooltip.style.display = 'none';
  tooltip.style.pointerEvents = 'none';
  tooltip.style.zIndex = '1001';
  document.body.appendChild(tooltip);
  return tooltip;
}

// Global state for filtering
let globalData = [];
let selectedCompany = null;
let selectedMinYear = 1971;
let baseMapLayer = null;
let isSliderActive = false;


// Function to update map display
function updateMapDisplay() {
  if (!globalData.length) return;
  
  // Filter data based on selected company and year
  let filteredData = globalData;
  
  // Filter by year first
  filteredData = filteredData.filter(d => d.year <= selectedMinYear);
  
  // Then filter by company
  if (selectedCompany) {
    filteredData = filteredData.filter(d => d.razao_social === selectedCompany);
  }
  
  // Create new icon layer and text layer with filtered data
  const iconLayer = createIconLayer(filteredData);
  const textLayer = createTextLayer(filteredData);
  
  // Update deck with new layers
  deck.setProps({
    layers: [baseMapLayer, iconLayer, textLayer]
  });
  
  // Update legend UI
  const legendItems = document.querySelectorAll('.company-stats li');
  legendItems.forEach(item => {
    const company = item.dataset.company;
    item.classList.remove('active', 'inactive');
    
    if (selectedCompany) {
      if (company === selectedCompany) {
        item.classList.add('active');
      } else {
        item.classList.add('inactive');
      }
    }
  });
  
  // Update year display
  updateYearDisplay();
}

// Initialize visualization
async function init() {
  const data = await loadData();
  
  if (data.length === 0) {
    console.error('No valid data to display');
    return;
  }

  globalData = data;
  const iconLayer = createIconLayer(data);
  const textLayer = createTextLayer(data);
  
  // Use CartoDB dark tiles which are more reliable
  baseMapLayer = new TileLayer({
    id: 'base-map',
    data: 'https://cartodb-basemaps-a.global.ssl.fastly.net/dark_all/{z}/{x}/{y}.png',
    minZoom: 0,
    maxZoom: 18,
    tileSize: 256,
    renderSubLayers: props => {
      const { west, south, east, north } = props.tile.bbox;
      return new BitmapLayer(props, {
        data: null,
        image: props.data,
        bounds: [west, south, east, north]
      });
    }
  });
  
  console.log('Setting layers on deck:', baseMapLayer, iconLayer, textLayer);
  deck.setProps({
    layers: [baseMapLayer, iconLayer, textLayer]
  });
  
  console.log('Deck props set, layers should render now');
  
  // Setup legend interactivity
  setupLegendInteractivity();
  
  // Setup year slider
  setupYearSlider();
}

// Setup legend click handlers
function setupLegendInteractivity() {
  const legendItems = document.querySelectorAll('.company-stats li');
  
  legendItems.forEach(item => {
    item.addEventListener('click', () => {
      const company = item.dataset.company;
      
      if (selectedCompany === company) {
        // Deselect if clicking the same company
        selectedCompany = null;
      } else {
        // Select the clicked company
        selectedCompany = company;
      }
      
      updateMapDisplay();
    });
  });
}

// Function to update year display
function updateYearDisplay() {
  const yearDisplay = document.getElementById('yearDisplay');
  if (yearDisplay) {
    yearDisplay.textContent = `Ano ${selectedMinYear}`;
  }
}

// Setup year slider functionality
function setupYearSlider() {
  const slider = document.getElementById('minYearSlider');
  
  if (slider) {
    // Show labels when slider interaction starts
    slider.addEventListener('mousedown', () => {
      isSliderActive = true;
      updateMapDisplay();
    });
    
    // Hide labels when slider interaction ends
    slider.addEventListener('mouseup', () => {
      isSliderActive = false;
      updateMapDisplay();
    });
    
    // Also hide labels when mouse leaves the slider while dragging
    slider.addEventListener('mouseleave', () => {
      if (isSliderActive) {
        isSliderActive = false;
        updateMapDisplay();
      }
    });
    
    // Update year value as slider moves
    slider.addEventListener('input', (e) => {
      selectedMinYear = parseInt(e.target.value);
      updateMapDisplay();
    });
    
    // Handle touch events for mobile
    slider.addEventListener('touchstart', () => {
      isSliderActive = true;
      updateMapDisplay();
    });
    
    slider.addEventListener('touchend', () => {
      isSliderActive = false;
      updateMapDisplay();
    });
  }
  
  // Initialize display
  updateYearDisplay();
}

// Start the application
init();